/**
 * 025 decision 14: the report, `scripts/cost/report.json`. Generated by
 * `bun run cost`, written in Prettier's JSON format, never edited by hand.
 * `030` reads it through `readCost` and words it through `costFacts`.
 */
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import * as prettier from "prettier";
import type { Interaction } from "./interactions.ts";
import { COST_DIR } from "./items.ts";

export const REPORT_PATH = path.join(COST_DIR, "report.json");

export type Size = {
  js: number;
  css: number;
  lazy: number;
  assets: number;
  brotli: { js: number; css: number };
};

export type Hydrate = {
  ms: number;
  spread: [number, number];
  /** Time to the fixture's `cost:settled` mark, for work begun at mount; not budgeted. */
  settledMs: number | null;
};

export type InteractionFigure = {
  kind: Interaction["kind"];
  start: Interaction["start"];
  says: Interaction["says"];
  /** The wait a person has, from the input to two frames after the change. Budgeted. */
  ms: number;
  spread: [number, number];
  /** `ms` minus the same run's no-op click: the item's own work, estimated. Not budgeted. */
  ownMs: number;
  /** `pointerup` minus `pointerdown`, for a click. */
  pressGapMs: number | null;
  /** Event Timing's largest duration for the interaction, in 8 ms steps; null under 16 ms or for a hover. */
  eventTimingMs: number | null;
};

export type CaseEntry = {
  hash: string;
  runtimeHash: string;
  run: string;
  size: Size;
  hydrate: Hydrate;
  interaction: InteractionFigure | null;
};

export type Entry = CaseEntry & {
  /** The page measured: `/`, or a block's route. */
  route: string;
  /** Initial JS by source, apportioned by rendered bytes; approximate. */
  breakdown: { source: string; js: number }[];
  cases: Record<string, CaseEntry>;
};

export type Run = {
  /** HEAD, with "+dirty" when the tree was not clean. */
  commit: string;
  full: boolean;
  machine: { model: string; cores: number; os: string };
  tools: {
    bun: string;
    chromium: string;
    playwright: string;
    cli: string;
    zlib: string;
  };
  settings: {
    cpu: number;
    launches: number;
    block: string;
    warmups: number;
    gzipLevel: number;
  };
  load: { median: number; max: number };
  instrument: { floorHydrateMs: number; noopMs: number; calibrateMs: number };
  noisy: boolean;
  /** The run's wall time, in seconds. */
  seconds: number;
};

export type Report = {
  schema: 1;
  runs: Record<string, Run>;
  /** The cost app with nothing added: gzipped bytes. */
  empty: { js: number; css: number };
  /** The theme item and `utils` added, nothing rendered from them. */
  themeFloor: {
    js: number;
    css: number;
    assets: number;
    fonts: Record<string, number>;
  };
  /** The theme floor whose page calls `cn` once. */
  floor: {
    js: number;
    css: number;
    run: string;
    hydrateMs: number;
    noopMs: number;
  };
  /** Every non-block item on one page, over the floor, beside the same items' alone figures summed. */
  catalogue: {
    js: number;
    css: number;
    sumOfAlone: { js: number; css: number };
  };
  items: Record<string, Entry>;
};

export function readReport(file = REPORT_PATH): Report {
  return JSON.parse(readFileSync(file, "utf8"));
}

/** Writes a JSON file as the repository's Prettier formats it. */
export async function writeJson(file: string, value: unknown): Promise<void> {
  const options = (await prettier.resolveConfig(file)) ?? {};
  const text = await prettier.format(JSON.stringify(value), {
    ...options,
    filepath: file,
  });
  writeFileSync(file, text);
}

export function writeReport(report: Report, file = REPORT_PATH) {
  return writeJson(file, report);
}

/** The newest run with `full: true`, by its id (its start time). */
export function newestFullRun(report: Report): Run | undefined {
  const ids = Object.keys(report.runs)
    .filter((id) => report.runs[id]!.full)
    .sort();
  return ids.length ? report.runs[ids.at(-1)!] : undefined;
}

/** An item's entry in the committed report, or null. */
export function readCost(name: string, report = readReport()): Entry | null {
  return report.items[name] ?? null;
}

/** How each start event is named in a note (decision 14). */
export const COST_NOTE_INPUT: Record<Interaction["start"], string> = {
  click: "click",
  pointerdown: "click",
  keydown: "key press",
  pointerover: "hover",
};

export type CostFacts = {
  /** Initial JS plus CSS: "39.4 kB". */
  size: string;
  /** "+ 133 kB on demand" when lazy JS and assets come to 0.1 kB or more; else null. */
  onDemand: string | null;
  /** "opens in 96 ms", "hydrates in 36 ms" or "hydrates in under 5 ms". */
  time: string;
  /** What the figures mean, for the facts line. */
  note: string;
};

const kB = (bytes: number) => bytes / 1000;

/** The strings `030` shows on a component page's facts line. */
export function costFacts(
  entry: Pick<Entry, "size" | "hydrate" | "interaction">,
  noopMs?: number,
): CostFacts {
  const size = `${kB(entry.size.js + entry.size.css).toFixed(1)} kB`;
  const lazy = Math.max(0, entry.size.lazy) + Math.max(0, entry.size.assets);
  const onDemand =
    lazy >= 50
      ? `+ ${kB(lazy) >= 10 ? Math.round(kB(lazy)) : kB(lazy).toFixed(1)} kB on demand`
      : null;
  const i = entry.interaction;
  if (i) {
    const noop = Math.round(noopMs ?? i.ms - i.ownMs);
    return {
      size,
      onDemand,
      time: `${i.says} in ${Math.round(i.ms)} ms`,
      note: `Alone, gzipped. Times under a 4× slower CPU, from the ${COST_NOTE_INPUT[i.start]} to the second frame after the change; an empty click measures ${noop} ms.`,
    };
  }
  return {
    size,
    onDemand,
    time:
      entry.hydrate.ms < 5
        ? "hydrates in under 5 ms"
        : `hydrates in ${Math.round(entry.hydrate.ms)} ms`,
    note: "Alone, gzipped. Hydration under a 4× slower CPU, over an empty page's.",
  };
}
